window.QUIZ = (window.QUIZ || []).concat([
  { id: "14-001", ch: 14, sec: "14.1", page: 297, type: "recall", level: 1,
    q: "Which five features characterize how microirrigation applies water?",
    opts: ["Low rates, long periods, frequent intervals, near the roots, low pressure", "High rates, short periods, rare intervals, whole surface, high pressure", "Low rates, short periods, weekly intervals, whole surface, high pressure", "High rates, long periods, frequent intervals, below roots, low pressure"], a: 0,
    why: "The book lists low rates, prolonged periods, frequent intervals, application near or into the root zone, and relatively low pressure.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-002", ch: 14, sec: "14.1", page: 297, type: "concept", level: 1,
    q: "Why does the book say microirrigation is best suited to high value crops, expensive land, or sites with environmental concerns?",
    opts: ["Most crops cannot adapt to drip", "The initial cost of the system is high", "It only works on sandy soils", "It needs more water than sprinklers"], a: 1,
    why: "Most crops adapt to microirrigation, and it is used on all soil types. The limit is the high initial cost, which the crop or site value must repay.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-003", ch: 14, sec: "14.1", page: 297, type: "recall", level: 1,
    q: "On which kinds of sites does the book say microirrigation is particularly useful?",
    opts: ["Deep clay soils with high water holding capacity on flat ground", "Fields with turbid canal water where filters are not practical", "Sandy or rocky soils, salt-affected soils and steep slopes", "Large grain fields with cheap labor and low value crops"], a: 2,
    why: "It is especially useful on very sandy and rocky soils, salt-affected soils, steep slopes, and where soil evaporation is a concern.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-004", ch: 14, sec: "14.1", page: 297, type: "recall", level: 2,
    q: "Which of these does the book list as a potential disadvantage of microirrigation?",
    opts: ["Increased weed growth across the whole field", "Higher energy needs than other pressurized systems", "Poor ability to apply fertilizers with the water", "Restricted root development and salt buildup near plants"], a: 3,
    why: "Disadvantages listed: high initial cost, persistent maintenance, restricted root development, and salt accumulation near plants. Limited weeds, lower energy and better fertilizer application are listed as advantages.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-005", ch: 14, sec: "14.1", page: 297, type: "concept", level: 2,
    q: "The small openings that give drip emitters their low flow cause what main problem, and what three solutions does the book give?",
    opts: ["Drift, solved by lower pressure, larger drops and windbreaks", "Runoff, solved by lower rates, surface storage and residue", "Clogging, solved by better emitters, filtration and chemicals", "Freezing, solved by draining, insulation and burial"], a: 2,
    why: "Low discharge needs small openings, which clog. The book's remedies are emitters needing less maintenance, adequate filtration, and chemical water treatment.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-006", ch: 14, sec: "14.1", page: 297, type: "recall", level: 1,
    q: "Which three questions does the book say a producer should answer before investing in microirrigation?",
    opts: ["Will yield gains pay for it, can the water be filtered, and which emitters fit", "Will it raise land value, can it run on gravity, and which pivot fits", "Will it cut labor to zero, can it run on canal water, and which pump fits", "Will it stop all weeds, can it apply manure, and which tape fits"], a: 0,
    why: "The book names profitability (will production increase enough), whether the water can be filtered to prevent clogging, and which emitters suit the purpose.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-007", ch: 14, sec: "14.2", page: 298, type: "recall", level: 2,
    q: "Who first experimented with subsurface trickle irrigation, and when?",
    opts: ["Sterling Davis in California, 1963", "Frank Zybach in Nebraska, 1948", "Keller and Bliesner in Utah, 1990", "E.B. House at Colorado State University, 1913"], a: 3,
    why: "E.B. House at Colorado State University tried subsurface trickle irrigation in 1913 but found it too expensive. Davis installed the first field SDI experiment in a lemon orchard in 1963.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-008", ch: 14, sec: "14.2", page: 298, type: "recall", level: 1,
    q: "What 1948 development provided an economical material for drip irrigation?",
    opts: ["Linear low-density polyethylene", "Low-density polyethylene pipe", "PVC pressure pipe", "Galvanized steel tubing"], a: 1,
    why: "The discovery of low-density polyethylene pipe in 1948 made drip practical. Linear low-density polyethylene came in 1977.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-009", ch: 14, sec: "14.2", page: 298, type: "recall", level: 2,
    q: "How many acres of microirrigation did the first U.S. survey in 1974 report, and which state had most of it?",
    opts: ["About 1.5 million acres, mostly in Florida", "About 3.1 million acres, mostly in California", "About 7,000 acres, mostly in Arizona", "About 70,000 acres, more than half in California"], a: 3,
    why: "The 1974 survey found about 70,000 acres, with California at 41,000. By 1990 it was 1.5 million and by 2000 about 3.1 million acres.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-010", ch: 14, sec: "14.2", page: 298, type: "recall", level: 1,
    q: "In 2018, about how many U.S. acres were microirrigated out of about 56 million irrigated acres?",
    opts: ["Nearly 6 million acres", "Nearly 1 million acres", "Nearly 15 million acres", "Nearly 25 million acres"], a: 0,
    why: "Nearly 6 million of about 56 million irrigated acres used microirrigation, under 11%. About 3 million were surface drip, just over 1 million SDI, and 1.5 million micro-sprinklers.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-011", ch: 14, sec: "14.3", page: 298, type: "recall", level: 1,
    q: "What are the four major microirrigation system types named in the book?",
    opts: ["Drip tape, porous pipe, sprinkler and furrow", "Surface drip, microspray, bubbler and subsurface drip", "Trickle, LEPA, bubbler and subirrigation", "Surface drip, center pivot, bubbler and flood"], a: 1,
    why: "The book separates surface drip, microspray (microsprinkler), bubbler and subsurface drip based on installation, emitter design or operation.",
    eq: null, calc: null, fig: "14.1", table: null },
  { id: "14-012", ch: 14, sec: "14.3", page: 299, type: "recall", level: 1,
    q: "What maximum discharge does the book give for individual surface drip emitters, and for line-source tubing?",
    opts: ["Under 30 gal/hr per emitter, under 10 gal/hr per foot of tubing", "Under 50 gal/hr per emitter, under 3 gal/hr per foot of tubing", "Under 3 gal/hr per emitter, under 1 gal/hr per foot of tubing", "Under 0.3 gal/hr per emitter, under 0.1 gal/hr per foot of tubing"], a: 2,
    why: "Surface drip emitters normally discharge less than 3 gal/hr, and porous tubing and other multiple outlet systems less than 1 gal/hr per foot.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-013", ch: 14, sec: "14.3", page: 300, type: "recall", level: 1,
    q: "What typical maximum discharges does the book give for a microspray applicator and for a bubbler?",
    opts: ["Under 3 gal/hr for microspray, under 6 gal/hr for a bubbler", "Under 50 gpm for microspray, under 60 gpm for a bubbler", "Under 500 gal/hr for microspray, under 600 gal/hr for a bubbler", "Under 50 gal/hr for microspray, under 60 gal/hr for a bubbler"], a: 3,
    why: "Microspray applicators typically discharge less than 50 gal/hr and bubblers usually less than 60 gal/hr, both far above drip emitters.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-014", ch: 14, sec: "14.3", page: 300, type: "concept", level: 2,
    q: "Why are bubblers usually paired with a small earthen basin around each plant?",
    opts: ["Their spray drifts in wind and the earthen berm blocks it", "They need a basin of standing water to build up pressure", "Their flow at one point usually exceeds the soil infiltration rate", "The basin stores injected fertilizer between irrigations"], a: 2,
    why: "A bubbler pours a small stream at one point at rates that normally exceed infiltration, so a dike holds the water while it soaks in.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-015", ch: 14, sec: "14.3", page: 299, type: "concept", level: 2,
    q: "What major advantage does surface drip have over other microirrigation types?",
    opts: ["You can see wetting patterns and measure each emitter's flow", "It needs no filtration of any kind, even from open water", "Laterals on the soil surface cannot be damaged by traffic", "It wets the entire soil surface, which aids germination"], a: 0,
    why: "Surface drip is easy to install, inspect, repair and clean, and you can check surface wetting and measure each emitter. Laterals on the ground can be damaged unless hung on a trellis.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-016", ch: 14, sec: "14.3", page: 300, type: "recall", level: 1,
    q: "How deep are subsurface drip laterals buried, according to the book?",
    opts: ["Always exactly 36 inches", "A few inches to 18 inches or more", "Only 0.5 to 1 inch", "Below the water table"], a: 1,
    why: "SDI is buried from a few inches to 18 inches or more. Shallow systems sit in permanent beds, while deep installations do not require crops in the same beds.",
    eq: null, calc: null, fig: "14.4", table: null },
  { id: "14-017", ch: 14, sec: "14.3", page: 300, type: "figure", level: 2,
    q: "In Figure 14.2, where does salt accumulate around a surface drip emitter compared with a microspray emitter?",
    opts: ["At the surface just past the wetted edge, farther out for microspray", "Directly under the emitter at the surface in both systems", "At the bottom of the root zone in both systems", "Only under microspray, because drip leaches salts downward"], a: 0,
    why: "The figure shows a salt wedge at the dry surface just beyond the moisture contour, close to the drip emitter and beyond the spray radius for microspray.",
    eq: null, calc: null, fig: "14.2", table: null },
  { id: "14-018", ch: 14, sec: "14.3", page: 300, type: "figure", level: 1,
    q: "Comparing the two halves of Figure 14.2, which system wets a wider area of the soil surface?",
    opts: ["Surface drip, because the saturated radius is larger", "Both wet the same surface area", "Microspray, because water spreads over the spray radius", "Neither wets the surface"], a: 2,
    why: "The drip emitter has only a small saturated radius at the surface. The microspray wets the full spray radius, so its wetted area is much wider.",
    eq: null, calc: null, fig: "14.2", table: null },
  { id: "14-019", ch: 14, sec: "14.3", page: 301, type: "figure", level: 2,
    q: "Figure 14.3 compares wetting under surface and subsurface drip. Where is the emitter in the subsurface case and what does that mean for the soil surface?",
    opts: ["At the surface, so the surface is wettest", "About 2.1 ft deep, below the root zone", "About 0.3 ft deep, so the surface is saturated", "About 0.9 ft deep, so the surface stays drier"], a: 3,
    why: "The SDI emitter sits near 0.9 ft depth and constant pressure head contours spread around it, leaving the surface drier and cutting soil evaporation.",
    eq: null, calc: null, fig: "14.3", table: null },
  { id: "14-020", ch: 14, sec: "14.3", page: 301, type: "figure", level: 2,
    q: "In Figure 14.3, how does the shape of the wetted zone around a subsurface emitter differ from that under a surface emitter?",
    opts: ["It extends only downward like the surface case", "It extends above and below the emitter, not only downward", "It is a thin layer only at the soil surface", "It is confined within 0.1 ft of the emitter"], a: 1,
    why: "Under surface drip, wetting spreads down and out from the surface. Around a buried emitter the contours surround it, with water moving up by capillarity as well as down.",
    eq: null, calc: null, fig: "14.3", table: null },
  { id: "14-021", ch: 14, sec: "14.3", page: 300, type: "scenario", level: 2,
    q: "A melon grower wants a drip system that lasts many years, stays out of the way of cultivation, and lets him irrigate during harvest. Which type do you suggest?",
    opts: ["Surface drip tape, which is replaced each crop and is easy to inspect", "Subsurface drip, which lasts a decade or more and allows harvest irrigation", "Microspray, which needs minimal filtration and wets a wide area", "Bubblers, which need only a few feet of head and little filtration"], a: 1,
    why: "The book lists these as SDI advantages: permanent installation lasting a decade or more, little interference with cultivation, and irrigating and harvesting melons or tomatoes at the same time.",
    eq: null, calc: null, fig: "14.1", table: null },
  { id: "14-022", ch: 14, sec: "14.3", page: 300, type: "scenario", level: 3,
    q: "A citrus grower on coarse sand with a pond that carries some algae asks whether drip or microspray suits his trees better. What do you tell him?",
    opts: ["Microspray, since it wets more area and needs less filtration, despite drift", "Drip, since drip needs the least filtration of any system type", "Drip, since a drip emitter wets a wider area than spray on sand", "Bubblers, since they need the finest filtration but wet the most"], a: 0,
    why: "On coarse soils drip would need many emitters to wet enough area, while sprays cover more surface. Microspray needs minimal filtration and maintenance, with drift and evaporation as the trade-off.",
    eq: null, calc: null, fig: "14.2", table: null },
  { id: "14-023", ch: 14, sec: "14.4", page: 301, type: "recall", level: 1,
    q: "What are the basic components of a microirrigation system listed in the book?",
    opts: ["Well, pivot, span, tower, nozzle and end gun", "Canal, gate, siphon, furrow, tailwater pit and pump", "Pump and control stations, mainline, manifolds, laterals and applicators", "Reservoir, sprinkler, riser, hand line, valve and nozzle"], a: 2,
    why: "The book lists the pump station, control station, mainline, manifold, laterals and water applicators (Figure 14.5).",
    eq: null, calc: null, fig: "14.5", table: null },
  { id: "14-024", ch: 14, sec: "14.4", page: 302, type: "recall", level: 1,
    q: "Where are chemicals injected relative to the primary filter at a microirrigation control station?",
    opts: ["After the secondary screen filter", "At the end of each lateral", "After the water meter", "Before the primary filter"], a: 3,
    why: "Chemicals are injected into the mainline before the primary filter, so any precipitates or particles are filtered. The primary filter sits after the pump and injection equipment.",
    eq: null, calc: null, fig: "14.6", table: null },
  { id: "14-025", ch: 14, sec: "14.4", page: 302, type: "figure", level: 1,
    q: "In Figure 14.6, what is item 4 between the pump and the chemical injection point?",
    opts: ["A media filter", "A water meter", "A backflow prevention unit", "A pressure regulating valve"], a: 2,
    why: "Item 4 is the backflow prevention unit, required when the system connects to a potential drinking water source or when chemicals are injected.",
    eq: null, calc: null, fig: "14.6", table: null },
  { id: "14-026", ch: 14, sec: "14.4", page: 302, type: "figure", level: 2,
    q: "In the control station of Figure 14.6, what is the order of the media filter (6), screen filter (7) and water meter (9) as water flows to the field?",
    opts: ["Screen filter, then media filter, then water meter", "Water meter, then media filter, then screen filter", "Media filter, then water meter, then screen filter", "Media filter, then screen filter, then water meter"], a: 3,
    why: "Figure 14.6 shows the media filter (F), then the strainer or screen filter (S), then the meter (M), then the pressure regulating valve (10). The media filter is primary and the screen is secondary.",
    eq: null, calc: null, fig: "14.6", table: null },
  { id: "14-027", ch: 14, sec: "14.4", page: 302, type: "figure", level: 2,
    q: "Figure 14.6 marks many possible pressure gauge locations (item 3). Where are gauges most important, and why?",
    opts: ["On each side of the filters, where a drop shows clogging", "Only at the pump, since the pump sets system pressure", "Only at the end of the mainline, near the laterals", "Only on the chemical tank, to check injection pressure"], a: 0,
    why: "The book stresses gauges on each side of filters. A large pressure drop from inlet to outlet means the filter needs cleaning. A gauge leaving the station confirms operating pressure.",
    eq: null, calc: null, fig: "14.6", table: null },
  { id: "14-028", ch: 14, sec: "14.4", page: 302, type: "concept", level: 2,
    q: "When is a backflow prevention unit required at a microirrigation control station?",
    opts: ["Only when the water source is an open pond or canal", "When connected to possible drinking water or injecting chemicals", "Only when the control station includes a media filter", "Only when the pump motor is larger than about 10 hp"], a: 1,
    why: "Backflow prevention stops water and chemicals from flowing back into the supply. It is required for any connection to potential drinking water or any chemical injection.",
    eq: null, calc: null, fig: "14.6", table: null },
  { id: "14-029", ch: 14, sec: "14.4", page: 303, type: "figure", level: 1,
    q: "What does Figure 14.7 show about water supply for small surface drip systems?",
    opts: ["A raised tank or bucket can feed drip by gravity with no pump", "Every drip system needs a pump at the control station", "Gravity drip needs a media filter and a booster pump", "Smallholder drip systems must use municipal water"], a: 0,
    why: "For some low pressure surface drip, a small tank, barrel or bucket delivers water by gravity, as in the smallholder examples in Figure 14.7.",
    eq: null, calc: null, fig: "14.7", table: null },
  { id: "14-030", ch: 14, sec: "14.4", page: 304, type: "calc", level: 1,
    q: "In Example 14.2, a 200 ft PE manifold carries 70 gpm in 2.5 in pipe with a friction loss of 0.96 psi/100 ft. What is the manifold friction loss?",
    opts: ["0.96 psi", "19.2 psi", "1.92 psi", "0.48 psi"], a: 2,
    why: "Loss = 0.96 psi/100 ft × 200 ft = 1.92 psi. The book calls this acceptable for a manifold. 2 in pipe was rejected because velocity would exceed 5 ft/s.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-031", ch: 14, sec: "14.4", page: 304, type: "concept", level: 2,
    q: "In Examples 14.1 and 14.2, what criterion is used to pick the smallest mainline or manifold pipe size?",
    opts: ["Friction loss below 20 psi per 100 ft", "Velocity above 10 ft/s", "Pipe wall at least 0.109 in", "Velocity below 5 ft/s"], a: 3,
    why: "Both examples choose the smallest size from Table 8.5 that keeps velocity under 5 ft/s: 4 in PVC for 200 gpm and 2.5 in PE for 70 gpm.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-032", ch: 14, sec: "14.4", page: 305, type: "concept", level: 3,
    q: "Why does the book recommend the Darcy-Weisbach equation instead of Hazen-Williams for drip laterals?",
    opts: ["Hazen-Williams overestimates friction loss in small pipe", "Hazen-Williams with C = 150 underestimates loss in small smooth pipe", "Darcy-Weisbach ignores pipe roughness, which is simpler", "Hazen-Williams cannot be used for flows below 100 gpm"], a: 1,
    why: "Keller and Bliesner found Hazen-Williams with C = 150 underestimates friction loss in small, smooth microirrigation pipe, so Table 14.1 uses Darcy-Weisbach (e = 0.0005 in).",
    eq: null, calc: null, fig: null, table: "14.1" },
  { id: "14-033", ch: 14, sec: "14.4", page: 305, type: "table", level: 1,
    q: "Using Table 14.1, what is the friction loss in 0.75 in nominal PE tubing carrying 4.0 gpm?",
    opts: ["1.64 psi/100 ft", "6.38 psi/100 ft", "0.51 psi/100 ft", "2.43 psi/100 ft"], a: 0,
    why: "Row 4.0 gpm, 0.75 in column reads 1.64 psi/100 ft. 6.38 is the 0.5 in column, 0.51 the 1.0 in column, and 2.43 is 5 gpm in 0.75 in tubing.",
    eq: null, calc: "tab-14.1", fig: null, table: "14.1" },
  { id: "14-034", ch: 14, sec: "14.4", page: 305, type: "table", level: 1,
    q: "Using Table 14.1, what is the inside diameter of 1.0 in nominal PE pipe, and its friction loss at 10 gpm?",
    opts: ["0.824 in and 2.62 psi/100 ft", "1.049 in and 0.33 psi/100 ft", "1.049 in and 2.62 psi/100 ft", "1.61 in and 0.33 psi/100 ft"], a: 2,
    why: "Table 14.1 lists 1.0 in nominal as 1.049 in inside diameter, with 2.62 psi/100 ft at 10 gpm. 0.33 psi/100 ft is for 1.5 in pipe (1.61 in ID).",
    eq: null, calc: "tab-14.1", fig: null, table: "14.1" },
  { id: "14-035", ch: 14, sec: "14.4", page: 305, type: "table", level: 2,
    q: "Using Table 14.1, what is the friction loss in 0.5 in PE tubing at 2.5 gpm, and how does it compare with 0.75 in tubing at the same flow?",
    opts: ["2.76 vs 2.43 psi/100 ft, nearly the same", "2.76 vs 0.72 psi/100 ft, nearly 4 times less", "0.72 vs 2.76 psi/100 ft, larger tube loses more", "1.86 vs 0.49 psi/100 ft, about 4 times less"], a: 1,
    why: "At 2.5 gpm: 0.5 in = 2.76, 0.75 in = 0.72 psi/100 ft. The modest step up in diameter cuts loss by nearly 4 times. 1.86 and 0.49 are the 2.0 gpm row.",
    eq: null, calc: "tab-14.1", fig: null, table: "14.1" },
  { id: "14-036", ch: 14, sec: "14.4", page: 305, type: "calc", level: 2,
    q: "A 250 ft drip lateral has a multiple outlet factor F = 0.36 and a friction loss of 2.5 psi/100 ft for the same pipe without outlets. What is the lateral friction loss by Eq. 14.1?",
    opts: ["6.25 psi", "0.90 psi", "22.5 psi", "2.25 psi"], a: 3,
    why: "PL = F L Pf = 0.36 × 250 ft × 2.5 psi/100 ft = 2.25 psi. 6.25 psi forgets the outlet factor (F = 1 is only for a pipe with no outlets).",
    eq: "14.1", calc: "eq-14.1", fig: null, table: null },
  { id: "14-037", ch: 14, sec: "14.4", page: 305, type: "calc", level: 1,
    q: "In Example 14.3, a 200 ft lateral has emitters every 2 ft, each discharging 2 gal/hr. What is the flow at the lateral inlet?",
    opts: ["About 200 gpm", "About 6.7 gpm", "About 1.7 gpm", "About 3.3 gpm"], a: 3,
    why: "n = 200/2 = 100 emitters. Q = 100 × 2 gal/hr = 200 gal/hr ÷ 60 = 3.3 gpm. 200 gpm confuses gal/hr with gpm.",
    eq: "14.1", calc: "lateral-design", fig: null, table: null },
  { id: "14-038", ch: 14, sec: "14.4", page: 306, type: "calc", level: 3,
    q: "In Example 14.3 (F = 0.35, 30 ft extra length for barbs), 0.5 in tubing has Pf = 4.7 psi/100 ft. What is the lateral friction loss, and is it acceptable at 15 psi design pressure?",
    opts: ["About 3.3 psi, which is within the 3 psi limit", "About 3.8 psi, which exceeds the 3 psi (20%) limit", "About 10.8 psi, which far exceeds the limit", "About 1.6 psi, which is within the limit"], a: 1,
    why: "PL = 0.35 × (200 + 30) × 4.7/100 = 3.78 psi, above 20% of 15 psi (3 psi). The 0.75 in tube gives 0.92 psi, so it is required. 3.3 psi drops the barb allowance and 10.8 psi forgets F.",
    eq: "14.1", calc: "lateral-design", fig: null, table: "14.1" },
  { id: "14-039", ch: 14, sec: "14.4", page: 306, type: "calc", level: 3,
    q: "A level 300 ft drip lateral has emitters every 1 ft at 0.5 gal/hr and runs at 12 psi. Barbs add 20 ft of length and F = 0.345. Using Table 14.1, which tube size keeps friction loss under 20% of design pressure?",
    opts: ["0.75 in (about 0.8 psi), since 0.5 in loses about 3.0 psi", "0.5 in (about 3.0 psi), since the limit is 3.6 psi", "0.5 in (about 0.8 psi), since the flow is only 2.5 gpm", "1.0 in is required, since 0.75 in loses about 2.4 psi"], a: 0,
    why: "Q = 300 × 0.5 = 150 gal/hr = 2.5 gpm. 0.5 in: 0.345 × 320 × 2.76/100 = 3.05 psi, over the 2.4 psi limit (20% of 12). 0.75 in: 0.345 × 320 × 0.72/100 = 0.79 psi, acceptable.",
    eq: "14.1", calc: "lateral-design", fig: null, table: "14.1" },
  { id: "14-040", ch: 14, sec: "14.4", page: 306, type: "calc", level: 2,
    q: "Example 14.4 gives F = 0.365, an effective length of 205 ft, and Pf = 4.0 psi/100 ft for 1 in tubing. What is the lateral friction loss?",
    opts: ["About 8.2 psi", "About 1.5 psi", "About 3.0 psi", "About 0.38 psi"], a: 2,
    why: "PL = 0.365 × 205 × 4.0/100 = 2.99 psi, just under the 3 psi limit. 0.38 psi is the 1.5 in tubing result, and 8.2 psi forgets F.",
    eq: "14.1", calc: "eq-14.1", fig: null, table: null },
  { id: "14-041", ch: 14, sec: "14.4", page: 305, type: "concept", level: 2,
    q: "What design criterion do Examples 14.3 and 14.4 use to judge lateral friction loss on level ground?",
    opts: ["Velocity under 1 ft/s at the far lateral end", "Friction under 1 psi per 100 ft of lateral", "Loss under 20% of the average lateral pressure", "Total loss under 50% of the inlet pressure"], a: 2,
    why: "Both examples accept a loss up to 20% of the design pressure (3 psi at 15 psi) on a level lateral.",
    eq: "14.1", calc: null, fig: null, table: null },
  { id: "14-042", ch: 14, sec: "14.4", page: 305, type: "concept", level: 3,
    q: "For a lateral with 100 uniformly spaced emitters, why is F about 0.35 rather than 1.0?",
    opts: ["Flow drops along the lateral, so most of it carries less than inlet flow", "The emitters push pressure back into the lateral as they discharge", "F accounts for the elevation gain from the manifold to the lateral end", "Only the first 35 of the 100 emitters receive water at full pressure"], a: 0,
    why: "With outlets, flow in each segment is less than the inlet flow and friction falls faster than flow. The reduction factor F is about 0.35 for many outlets. F = 1.0 only for pipe with no outlets.",
    eq: "14.1", calc: null, fig: null, table: null },
  { id: "14-043", ch: 14, sec: "14.4", page: 307, type: "recall", level: 2,
    q: "What maximum continuous operating pressure do several manufacturers recommend for 0.015 in wall drip tubing, and for thinner walls?",
    opts: ["30 psi for 0.015 in, 20 psi for thinner walls", "8 psi for 0.015 in, 15 psi for thinner walls", "45 psi for 0.015 in, 30 to 40 psi for thinner walls", "15 psi for 0.015 in, 8 to 12 psi for thinner walls"], a: 3,
    why: "Recommended pressures depend on wall thickness: 15 psi for 0.015 in walls and 8 to 12 psi for thinner walls.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-044", ch: 14, sec: "14.4", page: 308, type: "figure", level: 2,
    q: "Figure 14.9 shows porous-wall tubing. How does it release water?",
    opts: ["Punched orifices at fixed intervals along the wall", "Capillary-size pores in the wall ooze water under pressure", "An inner and outer chamber with exit holes", "Inserted button emitters on barbs"], a: 1,
    why: "Porous wall tubing is made of material with capillary-size pores that ooze water. Single chamber tubing uses punched orifices or inserted emitters, and double chamber tubing has main and auxiliary passages.",
    eq: null, calc: null, fig: "14.9", table: null },
  { id: "14-045", ch: 14, sec: "14.4", page: 302, type: "scenario", level: 2,
    q: "A grower with a small drip system says the pressure gauge leaving his control station reads 45 psi and his tape is rated 10 psi. What item from Figure 14.6 does he need?",
    opts: ["A pressure regulator or flow control valve", "A second backflow prevention unit", "A larger media filter tank", "A booster pump after the meter"], a: 0,
    why: "If pressure is excessive, a pressure regulator or flow control valve (item 10 in Figure 14.6) is required. Tape this thin should run at about 8 to 12 psi.",
    eq: null, calc: null, fig: "14.6", table: null },
  { id: "14-046", ch: 14, sec: "14.4", page: 302, type: "scenario", level: 2,
    q: "A grower wants to inject fertilizer downstream of his media filter so the filter stays clean. What do you tell him?",
    opts: ["Inject after the screen filter at the end of the mainline instead", "Inject at the well head, where no backflow device is needed", "Inject at the far end of each lateral, away from the filters", "Inject before the primary filter and install backflow prevention"], a: 3,
    why: "The book places chemical injection before the primary filter, and any chemical injection requires a backflow prevention unit to protect the water source.",
    eq: null, calc: null, fig: "14.6", table: null },
  { id: "14-047", ch: 14, sec: "14.4", page: 307, type: "scenario", level: 2,
    q: "A grower asks: \"My drip tape has an 0.008 inch wall. Can I run it at 20 psi so the far end gets more water?\" What do you tell him?",
    opts: ["Yes, all drip tape is rated to at least 30 psi continuous", "Yes, as long as the filters are clean and flushed", "No, thin wall tape is rated about 8 to 12 psi, so regulate pressure", "No, drip tape of any wall must run below 2 psi"], a: 2,
    why: "Manufacturers commonly recommend 15 psi maximum for 0.015 in walls and 8 to 12 psi for thinner walls. Uneven flow is better fixed with regulation, shorter laterals or larger tubing.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-048", ch: 14, sec: "14.5", page: 308, type: "table", level: 1,
    q: "Using Table 14.2, what plugging potential does irrigation water with 80 ppm suspended solids have?",
    opts: ["Minor", "Moderate", "Severe", "None"], a: 1,
    why: "Suspended solids under 50 ppm are minor, 50 to 100 ppm moderate, and over 100 ppm severe.",
    eq: null, calc: "tab-14.2", fig: null, table: "14.2" },
  { id: "14-049", ch: 14, sec: "14.5", page: 308, type: "table", level: 3,
    q: "A well water test shows pH 7.6, 1,200 ppm dissolved salts, 2.0 ppm manganese and 0.3 ppm hydrogen sulfide. Using Table 14.2, which factor rates severe?",
    opts: ["pH", "Salts", "Hydrogen sulfide", "Manganese"], a: 3,
    why: "Manganese over 1.5 ppm is severe. pH 7 to 8 is moderate, salts 500 to 2,000 ppm moderate, and H2S under 0.5 ppm minor.",
    eq: null, calc: "tab-14.2", fig: null, table: "14.2" },
  { id: "14-050", ch: 14, sec: "14.5", page: 308, type: "table", level: 1,
    q: "Using Table 14.2, at what iron concentration does plugging potential become severe?",
    opts: ["Above 0.1 ppm", "Above 1.5 ppm", "Above 0.5 ppm", "Above 2.0 ppm"], a: 1,
    why: "Iron under 0.1 ppm is minor, 0.1 to 1.5 ppm moderate, and over 1.5 ppm severe. 2.0 ppm is the severe limit for hydrogen sulfide.",
    eq: null, calc: "tab-14.2", fig: null, table: "14.2" },
  { id: "14-051", ch: 14, sec: "14.5", page: 308, type: "table", level: 2,
    q: "Using Table 14.2, how is a pond water with a bacteria population of 30,000 per ml rated for plugging potential?",
    opts: ["Moderate", "Minor", "Severe", "Not rated"], a: 0,
    why: "Bacteria populations under 10,000/ml are minor, 10,000 to 50,000 moderate, and over 50,000 severe.",
    eq: null, calc: "tab-14.2", fig: null, table: "14.2" },
  { id: "14-052", ch: 14, sec: "14.5", page: 309, type: "recall", level: 1,
    q: "What filtration setup does the book say is most common for microirrigation?",
    opts: ["A screen filter followed by a media filter", "A vortex separator alone", "A media filter followed by a screen filter", "A settling basin alone"], a: 2,
    why: "The common system is a primary media filter followed by a secondary screen filter. Sand-laden water should first pass through a sand separator or settling basin.",
    eq: null, calc: null, fig: "14.10", table: null },
  { id: "14-053", ch: 14, sec: "14.5", page: 309, type: "recall", level: 1,
    q: "As a rule, particles larger than what fraction of an emitter's flow passage should be removed?",
    opts: ["One-tenth of the passage diameter", "One-half of the passage diameter", "Equal to the passage diameter", "One-hundredth of the passage diameter"], a: 0,
    why: "Remove particles larger than one-tenth the orifice or passage diameter because particles can group and bridge the passage. Many manufacturers say particles larger than 0.003 to 0.006 in.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-054", ch: 14, sec: "14.5", page: 310, type: "recall", level: 1,
    q: "How long should water stay in a settling basin to remove most inorganic particles larger than about 0.003 in?",
    opts: ["At least 15 seconds", "At least 15 minutes", "At least 24 hours", "At least 4 hours"], a: 1,
    why: "If water remains at least 15 minutes, most inorganic particles above about 0.003 in settle. Basins should be long and narrow, inlet at one end and outlet at the other.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-055", ch: 14, sec: "14.5", page: 310, type: "concept", level: 2,
    q: "What can a vortex (centrifugal) sand separator remove, and what can it not?",
    opts: ["All organic material, but almost none of the sand", "Dissolved iron and calcium, but not sand or silt", "About 98% of the sand, but not low density organics", "Bacteria and algae, but not silt or fine sand"], a: 2,
    why: "Centrifugal force removes high density particles, about 98% of the sand caught by a 0.003 in screen. Organic matter has low density and passes through.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-056", ch: 14, sec: "14.5", page: 310, type: "concept", level: 2,
    q: "Why are media filters better than screens at catching algae and diatoms?",
    opts: ["Media filters have larger openings than screen filters", "Media filters kill algae chemically as water passes", "Screen filters cannot be cleaned while they are running", "Long, narrow particles are trapped through the media depth"], a: 3,
    why: "Media filters trap particles throughout the bed depth, so long, narrow particles like algae and diatoms are caught more readily than on a screen surface.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-057", ch: 14, sec: "14.5", page: 310, type: "recall", level: 2,
    q: "What pressure drop occurs across a clean media filter, and at what drop should it be flushed?",
    opts: ["3 to 5 psi clean, flush at 20 psi", "2 to 3 psi clean, flush at 10 psi", "0.5 psi clean, flush at 2 psi", "10 psi clean, flush at 30 psi"], a: 1,
    why: "A clean media filter loses 2 to 3 psi. Flushing is recommended when the drop reaches 10 psi. Screen filters are cleaned at 3 to 5 psi.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-058", ch: 14, sec: "14.5", page: 310, type: "recall", level: 2,
    q: "What maximum flow per area does the book allow through a screen filter, and how much open area does a 0.003 in stainless steel screen have?",
    opts: ["200 gpm per ft² of total area, and 24% open", "100 gpm per ft² of open area, and 58% open", "500 gpm per ft² of open area, and 42% open", "200 gpm per ft² of open area, and 58% open"], a: 3,
    why: "Flow should not exceed 200 gpm per ft² of open area. A 0.003 in stainless steel screen is 58% open, while nylon of the same opening is only 24% open.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-059", ch: 14, sec: "14.5", page: 311, type: "calc", level: 2,
    q: "A municipal supply serves a 300 gpm drip system through a stainless steel screen with 0.003 in openings (58% open). What total screen area is needed?",
    opts: ["About 1.5 ft²", "About 0.87 ft²", "About 2.6 ft²", "About 6.3 ft²"], a: 2,
    why: "Eq. 14.2: As = (Q/Qm)/Oa = (300/200)/0.58 = 2.6 ft², as in Example 14.5. 1.5 ft² ignores the open fraction, and 6.3 ft² uses the 24% nylon value.",
    eq: "14.2", calc: "eq-14.2", fig: null, table: null },
  { id: "14-060", ch: 14, sec: "14.5", page: 311, type: "calc", level: 2,
    q: "What total screen area is needed to filter 150 gpm through a 0.003 in stainless steel screen that is 58% open?",
    opts: ["About 1.3 ft²", "About 0.75 ft²", "About 3.1 ft²", "About 0.44 ft²"], a: 0,
    why: "As = (150/200)/0.58 = 0.75/0.58 = 1.29 ft². 0.75 ft² forgets the open area fraction, and 3.1 ft² uses nylon at 24%.",
    eq: "14.2", calc: "eq-14.2", fig: null, table: null },
  { id: "14-061", ch: 14, sec: "14.5", page: 311, type: "calc", level: 3,
    q: "A 150 gpm system uses a nylon screen with 0.003 in openings (24% open area) instead of stainless steel. How large must the screen be?",
    opts: ["About 1.3 ft²", "About 0.18 ft²", "About 0.75 ft²", "About 3.1 ft²"], a: 3,
    why: "As = (150/200)/0.24 = 3.1 ft², about 2.4 times the 1.3 ft² for stainless steel (58% open). 0.18 ft² multiplies by 0.24 instead of dividing.",
    eq: "14.2", calc: "eq-14.2", fig: null, table: null },
  { id: "14-062", ch: 14, sec: "14.5", page: 311, type: "concept", level: 2,
    q: "Why must the open area fraction be considered when sizing a screen filter?",
    opts: ["The open area changes as the flow rate through it changes", "Open area matters only for sizing media filters, not screens", "The mesh blocks much of the screen, and materials differ widely", "The open area sets the pressure rating of the filter housing"], a: 2,
    why: "The mesh obstructs much of the screen face. Stainless steel with 0.003 in openings is 58% open but equivalent nylon only 24%, so the same flow needs a much larger nylon screen.",
    eq: "14.2", calc: null, fig: null, table: null },
  { id: "14-063", ch: 14, sec: "14.5", page: 311, type: "concept", level: 3,
    q: "Why can't filtration alone prevent clogging from calcium and iron precipitates?",
    opts: ["They are far too large to pass through any filter screen", "They form after the filter as pH, temperature or evaporation change", "Filters dissolve the precipitates back into the water", "They form only in the well casing, before the pump"], a: 1,
    why: "Precipitates form downstream from changes in pH or temperature, and especially from evaporation at emitter outlets between irrigations. Chemical treatment is needed.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-064", ch: 14, sec: "14.5", page: 311, type: "recall", level: 2,
    q: "What water quality combination does the book say is likely to produce calcium deposits in a drip system?",
    opts: ["Bicarbonate above 2 meq/L (120 ppm) with pH above 7.5", "Bicarbonate above 0.5 meq/L with pH below 6", "Iron above 0.1 ppm with pH below 5.5", "Salts below 500 ppm with pH below 7"], a: 0,
    why: "Bicarbonate over 2 meq/L (120 ppm) together with pH over 7.5 is likely to deposit calcium. Acid injection to pH 5.5 to 7.0 prevents it.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-065", ch: 14, sec: "14.5", page: 311, type: "calc", level: 3,
    q: "Acid is typically injected at 0.02 to 0.2% of system capacity. For a 250 gpm drip system, what injection rate range is that?",
    opts: ["5 to 50 gpm", "0.5 to 5 gpm", "0.05 to 0.5 gpm", "0.005 to 0.05 gpm"], a: 2,
    why: "0.0002 × 250 = 0.05 gpm and 0.002 × 250 = 0.5 gpm. If more than 0.2% is needed, aerating and settling in a reservoir is usually cheaper.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-066", ch: 14, sec: "14.5", page: 311, type: "concept", level: 3,
    q: "When does the book say aerating and holding water in a reservoir is better than acid to control calcium?",
    opts: ["When the pH of the water is already below about 6", "When over about 0.2% acid would be needed for high bicarbonate", "When the water comes from a treated municipal supply", "When iron in the water is below about 0.1 ppm"], a: 1,
    why: "Acid at 0.02 to 0.2% of capacity is normal. Beyond 0.2%, aerating and holding water until it reaches equilibrium and the precipitate settles is more practical and cheaper.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-067", ch: 14, sec: "14.5", page: 311, type: "recall", level: 1,
    q: "How little soluble ferrous iron can cause precipitation problems in a drip system?",
    opts: ["As little as 0.3 ppm", "At least 3 ppm", "At least 10 ppm", "At least 30 ppm"], a: 0,
    why: "As little as 0.3 ppm ferrous iron can precipitate as reddish-brown ferric iron when oxidized. Up to 10 ppm can be handled with aeration and settling.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-068", ch: 14, sec: "14.5", page: 311, type: "concept", level: 2,
    q: "Why does the book prefer sodium hypochlorite over calcium hypochlorite for chlorinating drip water?",
    opts: ["Sodium hypochlorite is a solid and easier to store", "Calcium hypochlorite does not kill bacteria", "Sodium hypochlorite raises pH, which prevents deposits", "Calcium hypochlorite adds calcium that can precipitate"], a: 3,
    why: "Calcium hypochlorite brings calcium that may precipitate in the system, so sodium hypochlorite is preferred as the chlorine source.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-069", ch: 14, sec: "14.5", page: 312, type: "recall", level: 1,
    q: "What residual chlorine level does the book recommend to control algae and slime, and where is it measured?",
    opts: ["10 ppm at the control station", "0.1 ppm at the pump", "1.0 ppm at the far end of the system", "50 ppm at the first lateral"], a: 2,
    why: "A residual of 1.0 ppm measured at the far end usually prevents organic problems. The alternative is 10 to 20 ppm during the last 20 minutes of the irrigation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-070", ch: 14, sec: "14.5", page: 312, type: "concept", level: 1,
    q: "Why must light be kept out of a microirrigation system?",
    opts: ["Light breaks down the chlorine residual in the laterals", "Light heats water above the pipe pressure rating", "Light causes calcium carbonate to precipitate faster", "Algae need light, and pieces that pass filters grow inside"], a: 3,
    why: "Algae need sunlight. Small algae fragments pass filters and can grow inside clear or translucent components, so light must be excluded.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-071", ch: 14, sec: "14.5", page: 312, type: "recall", level: 1,
    q: "What minimum water velocity does the book recommend to flush fine particles from drip lines?",
    opts: ["At least 5 ft/s", "At least 1 ft/s", "At least 0.1 ft/s", "At least 10 ft/s"], a: 1,
    why: "A velocity of at least 1 ft/s is recommended to flush fine particles. 5 ft/s is the upper velocity limit used to size mainlines.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-072", ch: 14, sec: "14.5", page: 310, type: "concept", level: 2,
    q: "Why should small screen filters be placed at the inlet of each manifold or lateral even with a good main filter?",
    opts: ["They catch debris entering during main filter cleaning or breaks", "They replace the need to clean the main filters at the station", "They raise the pressure at the inlet of each lateral", "They remove dissolved iron before it reaches the emitters"], a: 0,
    why: "Auxiliary screens protect against debris entering during main filter cleaning or through breaks and openings in the distribution system.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-073", ch: 14, sec: "14.5", page: 312, type: "scenario", level: 2,
    q: "A grower says: \"My new drip system ran two days. The gauge before the sand filter reads 35 psi but after it dropped from 32 to 18 psi.\" What do you tell him?",
    opts: ["That drop is normal for a media filter in its first week, so leave it until it reaches 20 psi", "The pump is failing and losing pressure, so replace it before flushing the filter", "The 17 psi drop is past the 10 psi flush point, so flush now and consider automatic flushing", "The emitters downstream are clogged, so flush the laterals and leave the filter alone"], a: 2,
    why: "A clean media filter loses 2 to 3 psi and should be flushed at 10 psi. Reaching 17 psi in two days means frequent cleaning is needed, the case where automatic flushing on a timer or pressure differential pays.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-074", ch: 14, sec: "14.5", page: 312, type: "scenario", level: 2,
    q: "A grower just finished installing drip tape and a new mainline. What should he do before the first irrigation?",
    opts: ["Inject 50 ppm chlorine and let it sit in the lines for a week", "Run the system at double pressure for an hour to seat fittings", "Nothing is needed, since new pipe and tape come clean", "Flush the system by opening valves at the ends of all lines"], a: 3,
    why: "After installation or repairs, flush to remove foreign material by briefly opening valves at the ends of all pipelines. Every lateral should have an inexpensive flushing provision.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-075", ch: 14, sec: "14.5", page: 311, type: "scenario", level: 3,
    q: "A grower's well water has 4 ppm ferrous iron, and emitters are turning reddish-brown and plugging. What does the book recommend?",
    opts: ["Use a finer screen mesh and keep running the system", "Oxidize the iron and remove it before it enters the system", "Inject acid to pH 4 so the iron stays dissolved for good", "Raise system pressure to push the deposits out of emitters"], a: 1,
    why: "Iron should be precipitated deliberately and removed before it enters the system. Chlorine feeding oxidizes iron, and at up to 10 ppm mechanical aeration with settling time in a reservoir is practical.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-076", ch: 14, sec: "14.5", page: 311, type: "scenario", level: 3,
    q: "A grower's well tests at 180 ppm bicarbonate and pH 7.9, and white crust forms at emitter outlets. What do you recommend?",
    opts: ["Inject acid to pH 5.5 to 7.0, at the end of irrigations", "Install a finer screen filter after the media filter", "Switch from sodium to calcium hypochlorite", "Run the system less often to cut evaporation"], a: 0,
    why: "Bicarbonate above 120 ppm with pH above 7.5 is likely to deposit calcium. Acid to pH 5.5 to 7.0 prevents it, and treating at the end of irrigations or periodically saves cost.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-077", ch: 14, sec: "14.5", page: 310, type: "scenario", level: 3,
    q: "A grower pumping from a pond full of algae asks whether a screen filter alone is enough for his drip system. What do you say?",
    opts: ["Yes, a fine screen removes algae completely", "Yes, as long as he adds a vortex sand separator", "No, a settling basin alone will handle algae", "No, use media then screen filters, and chlorinate"], a: 3,
    why: "Media filters trap long, narrow algae and diatoms through the bed depth better than screens. Algae fragments that pass can grow inside, so chlorination is also needed. Vortex separators cannot remove low density organics.",
    eq: null, calc: null, fig: "14.10", table: null },
  { id: "14-078", ch: 14, sec: "14.5", page: 311, type: "scenario", level: 3,
    q: "A grower replaced a stainless steel screen with a nylon screen of the same size and 0.003 in openings. It now clogs much faster. Why?",
    opts: ["Nylon is about 24% open vs 58%, so it carries over twice the flow per open area", "Nylon openings stretch larger in use, so it passes and traps more debris", "Nylon screens cannot be backflushed, so debris stays on the screen face", "Nylon screens raise system pressure, which packs debris onto the mesh"], a: 0,
    why: "Eq. 14.2 sizes screens by open area. The same face area of nylon has 24/58 of the open area, so it needs about 2.4 times the size to stay under 200 gpm per ft² of open area.",
    eq: "14.2", calc: "eq-14.2", fig: null, table: null },
  { id: "14-079", ch: 14, sec: "14.5", page: 312, type: "scenario", level: 2,
    q: "A grower notices emitters near the ends of his laterals plugging with fine silt over the season while those near the manifold are fine. What do you recommend?",
    opts: ["Install a finer filter at the far end of each lateral line", "Install flushing valves at lateral ends and flush at 1 ft/s or more", "Raise the operating pressure to push the silt out of the emitters", "Run the system longer each day so the silt washes through"], a: 1,
    why: "Fine particles settle where flow slows toward lateral ends. The book calls for manual or automatic flushing devices at the end of each lateral and a flushing velocity of at least 1 ft/s.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-080", ch: 14, sec: "14.5", page: 312, type: "scenario", level: 2,
    q: "A grower using translucent tubing above ground from a farm pond finds green growth inside the laterals. What should he do?",
    opts: ["Switch to a finer screen filter at the control station", "Inject acid to bring the water to pH 5.5", "Keep light out and hold 1 ppm chlorine at the far end", "Flush the laterals once at the end of the season"], a: 2,
    why: "Algae fragments pass filters and grow where light gets in. Exclude light and chlorinate, holding about 1.0 ppm residual at the end of the system or 10 to 20 ppm in the last 20 minutes.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-081", ch: 14, sec: "14.6", page: 312, type: "recall", level: 1,
    q: "What discharge exponent x does the book give for fully turbulent orifice emitters and for laminar long path emitters?",
    opts: ["1.0 for turbulent, 0.5 for laminar", "0.0 for turbulent, 0.5 for laminar", "0.5 for turbulent, 1.0 for laminar", "0.42 for turbulent, 0.75 for laminar"], a: 2,
    why: "Fully turbulent emitters have x = 0.5 and laminar flow emitters x = 1.0. An x below 0.5 indicates pressure compensation.",
    eq: "14.3", calc: null, fig: null, table: null },
  { id: "14-082", ch: 14, sec: "14.6", page: 312, type: "calc", level: 2,
    q: "A vortex emitter has K = 0.24 and x = 0.42 (h in ft, q in gal/hr). What is its discharge at 20 psi?",
    opts: ["About 1.2 gal/hr", "About 0.9 gal/hr", "About 2.8 gal/hr", "About 11 gal/hr"], a: 0,
    why: "h = 20 × 2.31 = 46.2 ft. qe = 0.24 × 46.2^0.42 = 1.20 gal/hr. 0.9 gal/hr uses 20 ft instead of converting psi to feet.",
    eq: "14.3", calc: "eq-14.3", fig: null, table: null },
  { id: "14-083", ch: 14, sec: "14.6", page: 312, type: "calc", level: 2,
    q: "An orifice emitter has K = 0.30 and x = 0.5 (h in ft, q in gal/hr). What is its discharge at 10 psi?",
    opts: ["About 0.95 gal/hr", "About 3.0 gal/hr", "About 6.9 gal/hr", "About 1.4 gal/hr"], a: 3,
    why: "h = 10 × 2.31 = 23.1 ft. qe = 0.30 × 23.1^0.5 = 0.30 × 4.81 = 1.44 gal/hr. 0.95 gal/hr uses h = 10 ft, and 6.9 gal/hr forgets the square root.",
    eq: "14.3", calc: "eq-14.3", fig: null, table: null },
  { id: "14-084", ch: 14, sec: "14.6", page: 312, type: "calc", level: 2,
    q: "In Example 14.6, a vortex emitter discharges 0.75 gal/hr at 15 ft and 1.0 gal/hr at 30 ft. What is its discharge exponent x?",
    opts: ["About 0.50", "About 0.42", "About 0.75", "About 2.4"], a: 1,
    why: "Eq. 14.4: x = log(0.75/1.0)/log(15/30) = (−0.125)/(−0.301) = 0.42. 0.75 is just the flow ratio, and 2.4 inverts the logs.",
    eq: "14.4", calc: "eq-14.4", fig: null, table: null },
  { id: "14-085", ch: 14, sec: "14.6", page: 313, type: "calc", level: 3,
    q: "Using Example 14.6 (0.75 gal/hr at 15 ft, 1.0 gal/hr at 30 ft, x = 0.42), what is the discharge coefficient K?",
    opts: ["About 0.033", "About 0.75", "About 4.2", "About 0.24"], a: 3,
    why: "From Eq. 14.3, K = q/h^x = 1.0/30^0.42 = 1/4.2 = 0.24. 4.2 is h^x itself, and 0.033 divides by h without the exponent.",
    eq: "14.3", calc: "eq-14.4", fig: null, table: null },
  { id: "14-086", ch: 14, sec: "14.6", page: 312, type: "calc", level: 3,
    q: "An emitter delivers 1.8 gal/hr at 20 ft of head and 2.2 gal/hr at 30 ft. What is its discharge exponent, and what type of flow does that suggest?",
    opts: ["About 0.82, mostly laminar", "About 0.49, fully turbulent like an orifice", "About 0.20, pressure compensating", "About 1.0, fully laminar"], a: 1,
    why: "x = log(1.8/2.2)/log(20/30) = (−0.0872)/(−0.176) = 0.49. An x near 0.5 indicates fully turbulent, orifice-type flow.",
    eq: "14.4", calc: "eq-14.4", fig: null, table: null },
  { id: "14-087", ch: 14, sec: "14.6", page: 312, type: "calc", level: 3,
    q: "An emitter gives 0.9 gal/hr at 20 ft and 1.0 gal/hr at 40 ft of head. What is x, and is it pressure compensating?",
    opts: ["About 0.15, yes it compensates", "About 0.90, no it is laminar", "About 0.50, no it is turbulent", "About 0.11, no it is laminar"], a: 0,
    why: "x = log(0.9/1.0)/log(20/40) = (−0.0458)/(−0.301) = 0.15. Values below 0.5 indicate compensation, and this one is strongly compensating.",
    eq: "14.4", calc: "eq-14.4", fig: null, table: null },
  { id: "14-088", ch: 14, sec: "14.6", page: 313, type: "calc", level: 1,
    q: "An emitter type has v = 0.06 and an average discharge of 1 gal/hr. Within what range will about 95% of new emitters discharge?",
    opts: ["0.94 to 1.06 gal/hr", "0.82 to 1.18 gal/hr", "0.88 to 1.12 gal/hr", "0.76 to 1.24 gal/hr"], a: 2,
    why: "About 95% fall within ±2v of the mean: 1 ± 2(0.06) = 0.88 to 1.12 gal/hr, as the book states. 0.94 to 1.06 uses only ±1v.",
    eq: "14.5", calc: "eq-14.5", fig: null, table: null },
  { id: "14-089", ch: 14, sec: "14.6", page: 313, type: "calc", level: 3,
    q: "Eight new emitters tested at the same pressure give 1.02, 0.98, 1.05, 0.95, 1.00, 1.03, 0.97 and 1.00 gal/hr. What is v (Eq. 14.5), and how does Table 14.3 rate a drip emitter with that value?",
    opts: ["About 0.033, average", "About 0.10, marginal", "About 0.010, excellent", "About 0.033, excellent"], a: 3,
    why: "Mean = 1.00 gal/hr. The sample standard deviation (n − 1) is about 0.033, so v = 0.033/1.00 = 0.033. Drip emitters with v < 0.05 are excellent. In practice at least 50 emitters should be tested.",
    eq: "14.5", calc: "eq-14.5", fig: null, table: "14.3" },
  { id: "14-090", ch: 14, sec: "14.6", page: 313, type: "table", level: 1,
    q: "Using Table 14.3, how is a drip emitter with v = 0.09 classified?",
    opts: ["Marginal", "Average", "Poor", "Unacceptable"], a: 0,
    why: "For drip and spray emitters: below 0.05 excellent, 0.05 to 0.07 average, 0.07 to 0.11 marginal, 0.11 to 0.15 poor, above 0.15 unacceptable.",
    eq: null, calc: "tab-14.3", fig: null, table: "14.3" },
  { id: "14-091", ch: 14, sec: "14.6", page: 313, type: "table", level: 2,
    q: "Using Table 14.3, how is line-source drip tape with v = 0.15 classified?",
    opts: ["Marginal", "Average", "Poor", "Unacceptable"], a: 1,
    why: "Line-source tubing has a lower standard: below 0.1 excellent, 0.1 to 0.2 average, 0.2 to 0.3 poor, above 0.3 unacceptable. A drip emitter with v = 0.15 would be poor to unacceptable.",
    eq: null, calc: "tab-14.3", fig: null, table: "14.3" },
  { id: "14-092", ch: 14, sec: "14.6", page: 313, type: "concept", level: 2,
    q: "Why does Table 14.3 hold line-source tubing to a looser manufacturing variation standard than discrete emitters?",
    opts: ["Line-source tubing always runs at higher pressure than discrete emitters", "Tubing outlets are never measured, so their variation is unknown", "Low variation and low price are hard to get together, and row crops tolerate it", "Line-source tubing is used only on trees, which tolerate variation"], a: 2,
    why: "The book says keeping both variation and price low is difficult for tubing, and row crops served by closely spaced outlets are relatively insensitive to moderate variation.",
    eq: null, calc: null, fig: null, table: "14.3" },
  { id: "14-093", ch: 14, sec: "14.6", page: 314, type: "table", level: 1,
    q: "Using Table 14.4, what are the discharge exponent and manufacturing variation of a spiral path long-path emitter?",
    opts: ["x = 0.42, v = 0.07", "x = 0.70, v = 0.05", "x = 0.75, v = 0.06", "x = 0.20, v = 0.06"], a: 2,
    why: "Spiral path: x = 0.75, v = 0.06, manual flushing. 0.42/0.07 is vortex/orifice, 0.70/0.05 small tube, and 0.20/0.06 the automatic flushing compensating long-path emitter.",
    eq: null, calc: "tab-14.4", fig: null, table: "14.4" },
  { id: "14-094", ch: 14, sec: "14.6", page: 314, type: "table", level: 2,
    q: "Using Table 14.4, which emitter type has the lowest discharge exponent and therefore the least sensitivity to pressure?",
    opts: ["Slot and disc, x = 0.11", "Groove and flap, x = 0.33", "Compensating long path, x = 0.20", "Compensating ball and slotted seat, x = 0.25"], a: 0,
    why: "Slot and disc short path emitters have x = 0.11, the lowest in the table. Lower x means a flatter discharge curve.",
    eq: null, calc: "tab-14.4", fig: null, table: "14.4" },
  { id: "14-095", ch: 14, sec: "14.6", page: 314, type: "table", level: 3,
    q: "Using Table 14.4, which emitter has the worst manufacturing variation, and how would Table 14.3 rate it?",
    opts: ["Vortex orifice, v = 0.07, marginal for drip", "Slot and disc, v = 0.10, marginal for drip", "Twin chamber tubing, v = 0.17, poor for drip", "Ball and slotted seat, v = 0.27, unacceptable"], a: 3,
    why: "Among discrete emitters, ball and slotted seat has v = 0.27, well above the 0.15 unacceptable limit. Porous pipe (0.40) is higher but is line-source tubing.",
    eq: null, calc: "tab-14.4", fig: null, table: "14.4" },
  { id: "14-096", ch: 14, sec: "14.6", page: 314, type: "table", level: 2,
    q: "A grower wants an emitter with automatic flushing and low manufacturing variation. Using Table 14.4, which fits best?",
    opts: ["Tortuous long path, v = 0.02, no flushing", "Groove and flap, v = 0.02, automatic flushing", "Ball and slotted seat, v = 0.27, automatic flushing", "Small tube, v = 0.05, no flushing"], a: 1,
    why: "Groove and flap short path emitters have v = 0.02 and automatic flushing (x = 0.33). Tortuous path matches the v but has no flushing.",
    eq: null, calc: "tab-14.4", fig: null, table: "14.4" },
  { id: "14-097", ch: 14, sec: "14.6", page: 313, type: "figure", level: 1,
    q: "In Figure 14.11, which emitter type's discharge does not change with pressure head variation?",
    opts: ["Laminar, x = 1.0", "Fully compensating, x = 0.0", "Orifice, x = 0.5", "Vortex, x = 0.4"], a: 1,
    why: "The flat line at 0% discharge variation is the fully compensating emitter, x = 0.0. Steeper lines have larger x.",
    eq: null, calc: null, fig: "14.11", table: null },
  { id: "14-098", ch: 14, sec: "14.6", page: 313, type: "figure", level: 2,
    q: "From Figure 14.11, if pressure head drops 20% below rated, about how much does discharge drop for an orifice (turbulent) emitter?",
    opts: ["About 20%", "About 15%", "About 5%", "About 10 to 11%"], a: 3,
    why: "The x = 0.5 line reads about −10.6% at −20% head (0.8^0.5 = 0.894). A laminar emitter (x = 1.0) would drop 20%, and a long path x = 0.75 about 15%.",
    eq: null, calc: "eq-14.3", fig: "14.11", table: null },
  { id: "14-099", ch: 14, sec: "14.6", page: 313, type: "figure", level: 1,
    q: "From Figure 14.11, what discharge variation does a laminar emitter (x = 1.0) show at +30% pressure head?",
    opts: ["About +15%", "About +22%", "About +30%", "About +12%"], a: 2,
    why: "For x = 1.0, discharge varies one to one with head, so +30% head gives +30% flow. The x = 0.75 line is about +22% and x = 0.5 about +15%.",
    eq: null, calc: null, fig: "14.11", table: null },
  { id: "14-100", ch: 14, sec: "14.6", page: 313, type: "figure", level: 3,
    q: "Using Figure 14.11, which emitter line shows about +22% discharge at +30% head and about −23% at −30% head?",
    opts: ["Long path, x = 0.75", "Orifice or turbulent, x = 0.5", "Vortex, x = 0.4", "Laminar, x = 1.0"], a: 0,
    why: "The x = 0.75 line ends near +22% at the right and near −23% at the left (1.3^0.75 = 1.22, 0.7^0.75 = 0.77). The relationship is not symmetric because it is a power function.",
    eq: null, calc: null, fig: "14.11", table: null },
  { id: "14-101", ch: 14, sec: "14.6", page: 314, type: "concept", level: 2,
    q: "Within what pressure range should a system with laminar flow emitters (x near 1.0) be held, compared with turbulent emitters (x near 0.5)?",
    opts: ["About ±10% for laminar, up to ±5% for turbulent", "About ±5% for laminar, up to ±10% for turbulent", "About ±20% for both", "About ±1% for laminar, up to ±50% for turbulent"], a: 1,
    why: "With x near 1.0, pressure variation passes almost fully into discharge, so hold within about ±5%. Turbulent emitters (flow ∝ √h) tolerate up to ±10%.",
    eq: "14.3", calc: null, fig: null, table: null },
  { id: "14-102", ch: 14, sec: "14.6", page: 314, type: "calc", level: 1,
    q: "For a turbulent emitter with x = 0.5, how much must pressure head increase to double the discharge?",
    opts: ["2 times", "1.4 times", "8 times", "4 times"], a: 3,
    why: "q ∝ h^0.5, so doubling q needs h multiplied by 2² = 4. A laminar emitter (x = 1) would need only 2 times the head.",
    eq: "14.3", calc: "eq-14.3", fig: null, table: null },
  { id: "14-103", ch: 14, sec: "14.6", page: 314, type: "concept", level: 2,
    q: "What drawback does the book note for pressure compensating emitters?",
    opts: ["They always have high manufacturing variation", "They cannot be used on hilly or sloping ground", "Their moving parts fatigue and are affected by temperature", "They discharge more water as pressure rises"], a: 2,
    why: "Compensating emitters have a part that responds to pressure to hold flow constant. That part can fatigue and is sensitive to temperature changes.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-104", ch: 14, sec: "14.6", page: 314, type: "concept", level: 2,
    q: "For emitters with x between 0.2 and 0.35, what does the book say about flow regulation?",
    opts: ["Some regulation, with some room to adjust discharge", "Full compensation, with no room to adjust discharge", "They behave much like laminar long path emitters", "They cannot be used on sloping or hilly fields"], a: 0,
    why: "When x is between 0.2 and 0.35, flow compensating emitters give some regulation and still leave flexibility to adjust discharge. They are valuable on hilly sites.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-105", ch: 14, sec: "14.6", page: 314, type: "calc", level: 3,
    q: "In Example 14.7, a vortex emitter (K = 0.24, x = 0.42) runs at 15 psi at the header on a 1,000 ft field rising 1% away from it, with no friction. What is the discharge difference between the two ends?",
    opts: ["About 0.24 gal/hr (1.06 vs 0.82)", "About 0.08 gal/hr (1.06 vs 0.98)", "About 0.34 gal/hr (1.06 vs 0.72)", "About 0.14 gal/hr (1.06 vs 0.92)"], a: 3,
    why: "Header head = 15 × 2.3 = 34.5 ft, q = 0.24(34.5)^0.42 = 1.06 gal/hr. Far end head = 34.5 − 10 = 24.5 ft, q = 0.92 gal/hr. Difference 0.14 gal/hr, about 13%.",
    eq: "14.3", calc: "emitter-dq", fig: null, table: null },
  { id: "14-106", ch: 14, sec: "14.6", page: 314, type: "calc", level: 3,
    q: "Repeat Example 14.7 (K = 0.24, x = 0.42, 34.5 ft at the header, 10 ft rise to the far end) but add 5 ft of friction head loss along the lateral. What is the far-end discharge?",
    opts: ["About 0.84 gal/hr", "About 0.92 gal/hr", "About 0.70 gal/hr", "About 1.00 gal/hr"], a: 0,
    why: "hn = 34.5 − 10 − 5 = 19.5 ft. qn = 0.24 × 19.5^0.42 = 0.84 gal/hr, so the difference grows to 0.23 gal/hr. 0.92 ignores friction.",
    eq: "14.3", calc: "emitter-dq", fig: null, table: null },
  { id: "14-107", ch: 14, sec: "14.6", page: 314, type: "calc", level: 3,
    q: "If the Example 14.7 header (34.5 ft head, K = 0.24, x = 0.42) is moved to the high end so laterals run 10 ft downhill with no friction, what is the discharge at the low end?",
    opts: ["About 0.92 gal/hr, the lowest on the lateral", "About 1.06 gal/hr, the same as the header", "About 1.18 gal/hr, the highest on the lateral", "About 1.40 gal/hr, the highest on the lateral"], a: 2,
    why: "Downhill the elevation adds head: hn = 34.5 + 10 = 44.5 ft, q = 0.24 × 44.5^0.42 = 1.18 gal/hr. The difference from the header (1.06) is about 0.12 gal/hr.",
    eq: "14.3", calc: "emitter-dq", fig: null, table: null },
  { id: "14-108", ch: 14, sec: "14.6", page: 315, type: "concept", level: 1,
    q: "In Example 14.8 a pressure compensating emitter replaces the vortex emitter on the sloping field. What is the discharge difference between field ends?",
    opts: ["0.14 gal/hr, the same as the vortex emitter", "Zero, because the emitter is pressure compensating", "Twice that of the vortex emitter", "It cannot be determined without K"], a: 1,
    why: "With a compensating emitter discharge stays constant over the pressure range, so Δq = 0. That is why compensating emitters suit hilly sites.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-109", ch: 14, sec: "14.6", page: 314, type: "calc", level: 3,
    q: "A laminar flow emitter (x = 1.0) delivers 3.0 gal/hr at the header with 30 ft of head. Six feet up the slope the head is 24 ft. What is the discharge there?",
    opts: ["2.7 gal/hr", "3.0 gal/hr", "2.4 gal/hr", "1.8 gal/hr"], a: 2,
    why: "With x = 1, discharge is proportional to head: 3.0 × 24/30 = 2.4 gal/hr, a 20% drop. A turbulent emitter would give 3.0 × (0.8)^0.5 = 2.7 gal/hr.",
    eq: "14.3", calc: "emitter-dq", fig: null, table: null },
  { id: "14-110", ch: 14, sec: "14.6", page: 315, type: "calc", level: 2,
    q: "A field test of 12 emitters gives 1.9, 2.1, 2.0, 1.6, 2.2, 1.8, 2.0, 1.7, 2.1, 1.9, 2.0 and 1.5 gal/hr. What is the emission uniformity (Eq. 14.6)?",
    opts: ["About 79%", "About 89%", "About 95%", "About 84%"], a: 3,
    why: "Average of all = 22.8/12 = 1.90 gal/hr. Lowest one-fourth (3 readings) = 1.5, 1.6, 1.7, average 1.60. DU = 1.60/1.90 × 100 = 84%. 79% divides the minimum (1.5) by the mean.",
    eq: "14.6", calc: "eq-14.6", fig: null, table: null },
  { id: "14-111", ch: 14, sec: "14.6", page: 315, type: "calc", level: 3,
    q: "In Example 14.9, spiral long path emitters (x = 0.75, v = 0.06) run at an average 46.2 ft with 10 ft of friction loss on flat ground, 2 emitters per plant, average flow 1.0 gal/hr. What is the design DU?",
    opts: ["About 78%", "About 82%", "About 95%", "About 72%"], a: 0,
    why: "K = 1.0/46.2^0.75 = 0.056. Minimum head ≈ 36 ft gives qm ≈ 0.82 to 0.83 gal/hr. DU = 100(1 − 1.27 × 0.06/√2)(0.82) = 100(0.946)(0.82) ≈ 78%. 82% leaves out the manufacturing term.",
    eq: "14.7", calc: "eq-14.7", fig: null, table: "14.4" },
  { id: "14-112", ch: 14, sec: "14.6", page: 315, type: "calc", level: 2,
    q: "A design has v = 0.07, one emitter per plant, and qm/qa = 0.90. What is the design emission uniformity by Eq. 14.7?",
    opts: ["About 90%", "About 82%", "About 84%", "About 74%"], a: 1,
    why: "DU = 100(1 − 1.27 × 0.07/√1)(0.90) = 100(0.911)(0.90) = 82%. 90% ignores manufacturing variation.",
    eq: "14.7", calc: "eq-14.7", fig: null, table: null },
  { id: "14-113", ch: 14, sec: "14.6", page: 315, type: "calc", level: 3,
    q: "A design uses 4 emitters per plant with v = 0.05 and qm/qa = 0.95. What is the design DU?",
    opts: ["About 89%", "About 95%", "About 92%", "About 87%"], a: 2,
    why: "DU = 100(1 − 1.27 × 0.05/√4)(0.95) = 100(1 − 0.032)(0.95) = 92%. Using n = 1 would give 89%.",
    eq: "14.7", calc: "eq-14.7", fig: null, table: null },
  { id: "14-114", ch: 14, sec: "14.6", page: 315, type: "concept", level: 3,
    q: "In Eq. 14.7, why does adding more emitters per plant raise the design emission uniformity?",
    opts: ["More emitters per plant raise the minimum lateral pressure", "More emitters per plant reduce friction loss in the lateral", "More emitters per plant raise the average emitter discharge", "Variation averages out over more emitters, so 1.27 v/√n shrinks"], a: 3,
    why: "The manufacturing term is 1.27 v/√n. With more emitters per plant, individual high and low emitters average out, so each plant's water varies less.",
    eq: "14.7", calc: null, fig: null, table: null },
  { id: "14-115", ch: 14, sec: "14.6", page: 315, type: "scenario", level: 2,
    q: "A grower says: \"The emitters at the far end of my rows put out less than at the header. How do I check my system uniformity?\" What do you tell him?",
    opts: ["Read the pressure at the pump and compare it with the emitter label rating", "Measure emitter flows across the field and compute qLQ/qa", "Count the plugged emitters at the header end of each row and compare rows", "Measure soil moisture at one spot near the far end and compare with the header"], a: 1,
    why: "Eq. 14.6 field emission uniformity uses measured emitter flows across the system: DU = 100 qLQ/qa. Periodic checks catch blockage and wear.",
    eq: "14.6", calc: "eq-14.6", fig: null, table: null },
  { id: "14-116", ch: 14, sec: "14.6", page: 314, type: "scenario", level: 3,
    q: "A grower on a field with 25 ft of elevation change asks why his vortex emitters give uneven flow and what to do. What do you recommend?",
    opts: ["Use compensating emitters or regulated, shorter laterals", "Use laminar long path emitters, since they flush better", "Raise the header pressure by 25 ft to offset the slope", "Use longer laterals so the slope effect averages out"], a: 0,
    why: "On hilly ground, elevation differences change pressure along laterals. Compensating emitters or pressure regulated flow in short laterals are the book's solutions. Laminar emitters are the most sensitive to pressure.",
    eq: null, calc: null, fig: "14.11", table: null },
  { id: "14-117", ch: 14, sec: "14.6", page: 313, type: "scenario", level: 3,
    q: "A European emitter is rated 6 L/hr at 10 m of head. You measure 1 gal/hr at 15 ft. What is its flow at 20 ft, and is it pressure compensating?",
    opts: ["About 1.33 gal/hr, and no, x is about 1.0", "About 1.18 gal/hr, and no, x is about 0.59", "About 1.00 gal/hr, and yes, x is about 0", "About 1.15 gal/hr, and yes, x is about 0.5"], a: 1,
    why: "6 L/hr = 1.585 gal/hr and 10 m = 32.8 ft. x = log(1.585/1)/log(32.8/15) = 0.59, so K = 1/15^0.59. At 20 ft, q = 1 × (20/15)^0.59 = 1.18 gal/hr. Since x > 0.5 it is not compensating.",
    eq: "14.4", calc: "eq-14.4", fig: null, table: null },
  { id: "14-118", ch: 14, sec: "14.6", page: 314, type: "scenario", level: 3,
    q: "A vineyard on rolling hills must pick between emitter A (x = 0.75, v = 0.03) and emitter B (x = 0.20, v = 0.06). Which do you recommend and why?",
    opts: ["A, since its lower v always gives better uniformity", "A, since emitters with higher x flush better", "Either, since x does not matter on slopes", "B, since its low x keeps flow steady as pressure varies"], a: 3,
    why: "On hilly sites elevation changes cause large pressure swings. With x = 0.75 a 20% pressure change gives about 15% flow change, while x = 0.20 gives about 4%. That outweighs the small difference in v.",
    eq: null, calc: null, fig: "14.11", table: null },
  { id: "14-119", ch: 14, sec: "14.6", page: 313, type: "figure", level: 2,
    q: "From Figure 14.11, about how much does a vortex emitter (x = 0.4) discharge change when pressure head is 30% above rated?",
    opts: ["About +30%", "About +15%", "About +12%", "About 0%"], a: 2,
    why: "The x = 0.4 line ends near +12% at +30% head (1.3^0.4 = 1.11). The orifice line (x = 0.5) reaches about +15% and the laminar line +30%.",
    eq: null, calc: null, fig: "14.11", table: null },
  { id: "14-120", ch: 14, sec: "14.6", page: 314, type: "table", level: 1,
    q: "Using Table 14.4, which emitter type has continuous flushing ability?",
    opts: ["Multiple flexible orifices", "Vortex orifice", "Spiral path", "Slot and disc"], a: 0,
    why: "Multiple flexible orifices (x = 0.7, v = 0.05) is the only type listed with continuous flushing. Spiral path is manual, slot and disc automatic, and vortex has none.",
    eq: null, calc: "tab-14.4", fig: null, table: "14.4" },
  { id: "14-121", ch: 14, sec: "14.7", page: 316, type: "recall", level: 1,
    q: "What fraction of the soil surface does the book suggest wetting for widely spaced crops such as vines, bushes and trees?",
    opts: ["One-third to two-thirds of the area per plant", "Between 5 and 10% of the area per plant", "The entire area per plant", "Exactly one-half of the area per plant"], a: 0,
    why: "A reasonable design objective is to wet one-third to two-thirds of each plant's area. Higher Pw stores more water in case of system failure, and keeping it under two-thirds leaves dry strips for operations.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-122", ch: 14, sec: "14.7", page: 316, type: "concept", level: 2,
    q: "Why is a higher percent wetted area (Pw) valuable even though no minimum has been established?",
    opts: ["It reduces the number of emitters needed per plant", "It lowers evaporation from the wetted soil surface", "More stored soil water protects the crop if the system fails", "It keeps dry strips open for cultural practices"], a: 2,
    why: "Higher Pw means more stored water in the root zone, a buffer if irrigation stops. Keeping Pw below two-thirds is what maintains dry strips.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-123", ch: 14, sec: "14.7", page: 316, type: "concept", level: 2,
    q: "Why are spray emitters often used instead of drip on coarse-textured soils?",
    opts: ["Coarse soils clog drip emitters with sand particles", "Spray emitters have lower evaporation losses than drip", "Spray emitters run at a lower pressure than drip", "They wet more surface where drip would need many emitters"], a: 3,
    why: "Water spreads little laterally in coarse soils, so wetting enough area with drip would take many emitters. A spray emitter wets a much larger area.",
    eq: null, calc: null, fig: "14.2", table: null },
  { id: "14-124", ch: 14, sec: "14.7", page: 316, type: "concept", level: 2,
    q: "What is the main salinity advantage of microirrigation?",
    opts: ["Salts are fully leached out of the whole profile every irrigation", "The root zone stays wet and steady, so salt concentration stays low", "Salt never accumulates anywhere near the plants", "Drip water is always lower in salt"], a: 1,
    why: "Frequent irrigation keeps water content high and steady, so salt concentration in the soil solution stays low and steady instead of rising as soil dries between irrigations.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-125", ch: 14, sec: "14.7", page: 316, type: "scenario", level: 3,
    q: "A grower drip irrigating with saline water asks what risks to watch if he changes his row spacing next year or if a light rain falls after a dry spell. What do you tell him?",
    opts: ["Rain or a row shift can move edge salts into the root zone, so leach first", "No risk, because drip keeps salt away from roots permanently", "Light rain always leaches the salt below the root zone", "Shifting rows reduces salt problems, since roots find fresh soil"], a: 0,
    why: "Uneven salt distribution is a drip disadvantage. Shallow salts can be flushed into the root zone by rainfall, and shifting row geometry can put roots in high-salt areas if salts have not been leached.",
    eq: null, calc: null, fig: "14.2", table: null },
  { id: "14-126", ch: 14, sec: "14.7", page: 316, type: "calc", level: 1,
    q: "A drip-irrigated crop uses 0.30 in/day and effective rain adds 0.10 in. With no runoff, no deep percolation and no change in storage, what is the gross irrigation requirement?",
    opts: ["0.40 in/day", "0.20 in/day", "0.30 in/day", "0.10 in/day"], a: 1,
    why: "Eq. 14.8: dg = ET + dp + dr − Pe − ΔS = 0.30 + 0 + 0 − 0.10 − 0 = 0.20 in/day. 0.40 adds the rain instead of subtracting it.",
    eq: "14.8", calc: "eq-14.8", fig: null, table: null },
  { id: "14-127", ch: 14, sec: "14.7", page: 317, type: "calc", level: 3,
    q: "A drip system must apply a gross depth of 1.5 in over 8 acres. What volume of water is that?",
    opts: ["About 271,500 gal", "About 40,700 gal", "About 326,000 gal", "About 3.26 million gal"], a: 2,
    why: "Volume = 1.5 in × 8 ac = 12 ac-in. 1 ac-in = 27,154 gal, so 12 × 27,154 = 325,848 gal. 271,540 gal is the book's 10 ac-in example.",
    eq: "14.8", calc: "eq-14.8", fig: null, table: null },
  { id: "14-128", ch: 14, sec: "14.7", page: 317, type: "concept", level: 2,
    q: "For a well-managed microirrigation system without a salinity hazard, which terms of Eq. 14.8 are normally zero?",
    opts: ["ET and effective precipitation", "Only effective precipitation", "ET, deep percolation and storage change", "Runoff, deep percolation and storage change"], a: 3,
    why: "Drip aims to keep soil water constant (ΔS = 0), runoff should be zero, and without a salinity hazard no drainage water is needed, so dg ≈ ET − Pe.",
    eq: "14.8", calc: null, fig: null, table: null },
  { id: "14-129", ch: 14, sec: "14.7", page: 317, type: "recall", level: 1,
    q: "What is the maximum number of hours per day the book says a microirrigation system should be designed to run?",
    opts: ["12 hours", "20 hours", "24 hours", "8 hours"], a: 1,
    why: "Operating time should not exceed 20 hr/day, leaving time to catch up after repairs or maintenance, especially at peak water use.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-130", ch: 14, sec: "14.7", page: 317, type: "calc", level: 3,
    q: "A 10 ac drip block needs a gross 0.30 in/day at peak. If the system may run only 20 hr/day, what minimum flow is needed?",
    opts: ["About 57 gpm", "About 1,360 gpm", "About 34 gpm", "About 68 gpm"], a: 3,
    why: "Volume = 0.30 in × 10 ac = 3 ac-in = 81,460 gal. Over 20 hr (1,200 min): 81,460/1,200 = 68 gpm. 57 gpm spreads it over 24 hr.",
    eq: "14.8", calc: null, fig: null, table: null },
  { id: "14-131", ch: 14, sec: "14.7", page: 317, type: "calc", level: 2,
    q: "How many emitters are needed per acre to apply a gross 0.25 in in 4 hours with emitters discharging 0.5 gal/hr?",
    opts: ["About 3,400 emitters", "About 850 emitters", "About 13,600 emitters", "About 1,700 emitters"], a: 0,
    why: "Eq. 14.9: n = dg A/(qe t). Volume = 0.25/12 ft × 43,560 ft² × 7.48 gal/ft³ = 6,790 gal. n = 6,790/(0.5 × 4) = 3,394 emitters, about 12.8 ft² each.",
    eq: "14.9", calc: "eq-14.9", fig: null, table: null },
  { id: "14-132", ch: 14, sec: "14.7", page: 317, type: "calc", level: 2,
    q: "In Example 14.10 (dg = 0.27 in, qe = 2 gal/hr, 1 hr of irrigation per day, one lateral per row), what area does each emitter irrigate?",
    opts: ["About 6 ft²", "About 24 ft²", "About 12 ft²", "About 288 ft²"], a: 2,
    why: "A = qe t/dg = (2 gal/hr ÷ 7.48 gal/ft³ × 1 hr)/(0.27/12 ft) = 0.267/0.0225 = 12 ft². With one lateral per two rows, each emitter serves 6 ft². 288 ft² uses 24 hr.",
    eq: "14.9", calc: "eq-14.9", fig: null, table: null },
  { id: "14-133", ch: 14, sec: "14.7", page: 317, type: "calc", level: 2,
    q: "A drip system must apply 0.20 in/day using 1 gal/hr emitters running 2 hr/day. What area does each emitter serve?",
    opts: ["About 8 ft²", "About 32 ft²", "About 1.3 ft²", "About 16 ft²"], a: 3,
    why: "A = (1 × 2/7.48 ft³)/(0.20/12 ft) = 0.267/0.0167 = 16 ft². 8 ft² uses 1 hr and 1.3 ft² forgets to convert gallons to cubic feet.",
    eq: "14.9", calc: "eq-14.9", fig: null, table: null },
  { id: "14-134", ch: 14, sec: "14.7", page: 317, type: "calc", level: 3,
    q: "Tomato rows are 3 ft apart with one drip lateral per row, and each emitter must serve 12 ft². What emitter spacing along the lateral is needed?",
    opts: ["2 ft", "4 ft", "12 ft", "36 ft"], a: 1,
    why: "Area per emitter = row spacing × emitter spacing, so spacing = 12/3 = 4 ft. With one lateral per two rows (6 ft) it would be 2 ft.",
    eq: "14.9", calc: "eq-14.9", fig: null, table: null },
  { id: "14-135", ch: 14, sec: "14.7", page: 317, type: "calc", level: 3,
    q: "Drip laterals are 5 ft apart with emitters every 1.5 ft at 0.4 gal/hr. How long must the system run to apply a gross 0.25 in?",
    opts: ["About 2.9 hr", "About 1.5 hr", "About 0.4 hr", "About 7.3 hr"], a: 0,
    why: "Area per emitter = 5 × 1.5 = 7.5 ft². Volume = 0.25/12 × 7.5 = 0.156 ft³ × 7.48 = 1.17 gal. t = 1.17/0.4 = 2.9 hr.",
    eq: "14.9", calc: "drip-runtime", fig: null, table: null },
  { id: "14-136", ch: 14, sec: "14.7", page: 316, type: "concept", level: 2,
    q: "Why do young or widely spaced microirrigated crops use less water than conventional estimates that assume full cover?",
    opts: ["Young trees transpire faster per leaf area than mature trees do", "Drip systems capture more of the rainfall that falls on the field", "Drip keeps most of the surface dry, so little is lost to evaporation or weeds", "Conventional ET estimates ignore transpiration from partial canopies"], a: 2,
    why: "Conventional estimates for partial canopies assume losses from wet soil and unwanted vegetation. Drip keeps those minimal, so crop transpiration accounts for nearly all water use.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-137", ch: 14, sec: "14.7", page: 316, type: "scenario", level: 1,
    q: "A grower used to furrow irrigating asks how often his new drip system should run. What do you tell him?",
    opts: ["Once every two weeks with a large application", "Small, frequent amounts, often daily or every other day", "Only when the plants begin to wilt in the afternoon", "Continuously, 24 hours a day for the whole season"], a: 1,
    why: "Microirrigation is built for small, frequent irrigations, from once in several days to several times a day, with many systems running daily or every other day. Design should leave runtime under 20 hr/day.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-138", ch: 14, sec: "14.7", page: 317, type: "scenario", level: 2,
    q: "A grower asks why his dealer designed his drip system to finish the peak day in 18 hours instead of 24. What is the reason?",
    opts: ["Emitters overheat if they run more than 18 hours", "Filters cannot be flushed while the system runs", "Spare hours let it catch up after repairs at peak use", "Power rates prohibit pumping more than 18 hours"], a: 2,
    why: "The book limits operation to 20 hr/day so the system can catch up after downtime, which matters most at peak crop water use.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-139", ch: 14, sec: "14.7", page: 316, type: "scenario", level: 2,
    q: "An orchard grower in a rainy region with fine-textured soil asks whether wetting only about 25% of each tree's area is acceptable. What do you say?",
    opts: ["No, the book requires at least two-thirds wetted in every region", "No, every tree needs its whole area wetted to avoid stress", "Yes, but only on coarse sandy soils where water spreads widely", "Yes, with considerable rain, under one-third is acceptable on fine soils"], a: 3,
    why: "The usual target is one-third to two-thirds, but with considerable supplemental rainfall the book accepts Pw below one-third on fine-textured soils.",
    eq: null, calc: null, fig: null, table: null },
  { id: "14-140", ch: 14, sec: "14.8", page: 317, type: "recall", level: 1,
    q: "According to the summary, what is a major concern with microirrigation that drives filter selection?",
    opts: ["The potential for clogging emitters", "The potential for runoff", "Wind drift", "Frost damage"], a: 0,
    why: "The summary names clogging as a major concern and describes filters and the materials that cause clogging.",
    eq: null, calc: null, fig: null, table: null }
]);
